package it.penny.api.records;
import it.penny.api.security.*;
import it.penny.api.common.AuditLog;
import java.util.*;
import java.time.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController
public class RecordOperationsController {
 private final JdbcTemplate db;private final CustomerRecordService records;private final AuditLog audit;private final PennyUserRepository users;private final RbacService rbac;
 public RecordOperationsController(JdbcTemplate db,CustomerRecordService records,AuditLog audit,PennyUserRepository users,RbacService rbac){this.db=db;this.records=records;this.audit=audit;this.users=users;this.rbac=rbac;}
 private ResponseStatusException bad(String text){return new ResponseStatusException(HttpStatus.BAD_REQUEST,text);}
 private void optionsRead(Authentication auth){var u=auth==null?null:users.findByEmailIgnoreCase(auth.getName()).orElse(null);if(u==null||!u.enabled||u.mustChangePassword||!List.of("CUSTOMERS_READ","PRODUCTS_READ","CATALOG_READ","TRAINING_READ","CONTRACTS_READ","ACTIVITIES_READ","DATA_MANAGE").stream().anyMatch(p->rbac.allowed(u.id,p)))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}
 @GetMapping("/api/record-options/users") public Map<String,Object> users(Authentication auth){optionsRead(auth);var rows=db.queryForList("SELECT id,full_name AS name FROM penny_users WHERE enabled=true ORDER BY lower(full_name),id");return Map.of("items",rows,"total",rows.size());}
 @GetMapping("/api/choices") public Map<String,Object> choices(@RequestParam(required=false)String group,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="100")int size,Authentication auth){optionsRead(auth);if(page<0||page>100000||size<1||size>100)throw bad("Paginazione non valida");String projection="SELECT id,group_code AS \"group\",code,label AS name,label,active FROM penny_choices";if(group!=null){var rows=db.queryForList(projection+" WHERE group_code=? AND active=true ORDER BY label,id",group);return Map.of("items",rows,"total",rows.size());}return Map.of("items",db.queryForList(projection+" ORDER BY group_code,label,id LIMIT ? OFFSET ?",size,page*size),"total",Objects.requireNonNull(db.queryForObject("SELECT count(*) FROM penny_choices",Long.class)));}
 public record ChoiceInput(String group,String code,String label,Boolean active){}
 @PostMapping("/api/choices") @Transactional public Map<String,Object> choice(@RequestBody ChoiceInput in,Authentication auth){records.require(auth,"DATA_MANAGE");if(in.group()==null||!in.group().matches("[A-Za-z][A-Za-z0-9_]{0,59}")||in.label()==null||in.label().isBlank()||in.label().length()>200)throw bad("Scelta non valida");String code=in.code()==null||in.code().isBlank()?in.label().trim():in.code().trim();if(code.length()>120)throw bad("Codice troppo lungo");long id=db.queryForObject("INSERT INTO penny_choices(group_code,code,label,active) VALUES (?,?,?,?) RETURNING id",Long.class,in.group(),code,in.label().trim(),in.active()==null||in.active());audit.record(auth,"CHOICE_CREATED","CHOICE",id,Map.of("group",in.group()));return Map.of("id",id);}
 @PutMapping("/api/choices/{id}") @Transactional public Map<String,Object> choice(@PathVariable long id,@RequestBody ChoiceInput in,Authentication auth){records.require(auth,"DATA_MANAGE");if(in.label()==null||in.label().isBlank()||in.label().length()>200||in.active()==null)throw bad("Scelta non valida");if(db.update("UPDATE penny_choices SET label=?,active=? WHERE id=? AND group_code=? AND code=?",in.label().trim(),in.active(),id,in.group(),in.code())==0)throw bad("Scelta inesistente: codice e gruppo non modificabili");audit.record(auth,"CHOICE_UPDATED","CHOICE",id,Map.of("active",in.active()));return Map.of("updated",true);}
 private Map<String,Object> owner(long id,Authentication auth,boolean write){var row=records.get(id,auth);if(write)records.require(auth,CustomerRecordService.permission((String)row.get("kind"))+"_WRITE");return row;}
 @GetMapping("/api/customers/{customerId}/support-coverage") public Map<String,Object> coverage(@PathVariable long customerId,Authentication auth){records.require(auth,"CUSTOMERS_READ");var customers=db.queryForList("SELECT lifecycle_status FROM penny_customers WHERE id=? AND deleted_at IS NULL",customerId);if(customers.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);boolean has=db.queryForObject("SELECT count(*) FROM penny_customer_records WHERE customer_id=? AND kind='CONTRACT' AND deleted_at IS NULL AND status IN ('ACTIVE','EXPIRING') AND ((starts_on IS NULL OR starts_on<=current_date) AND (expires_on IS NULL OR expires_on>=current_date) OR EXISTS(SELECT 1 FROM penny_contract_renewals h WHERE h.record_id=penny_customer_records.id AND h.event_type='RENEWAL' AND (h.previous_start IS NULL OR h.previous_start<=current_date) AND h.previous_end>=current_date)) AND (details->>'contractType' IN ('PHONE','PHONE_UPDATES','HOURLY') OR details->>'assistanceBase'='HOURLY')",Long.class,customerId)>0;return Map.of("requiresContract","CUSTOMER".equals(customers.getFirst().get("lifecycle_status")),"hasSupport",has);}
 @GetMapping("/api/customer-records/{id}/tasks") public Map<String,Object> tasks(@PathVariable long id,Authentication auth){owner(id,auth,false);var rows=db.queryForList("SELECT t.id,t.name,t.assignee_id AS \"assigneeId\",u.full_name AS \"assigneeName\",t.progress,t.starts_on AS \"startsOn\",t.ends_on AS \"endsOn\" FROM penny_record_tasks t LEFT JOIN penny_users u ON u.id=t.assignee_id WHERE record_id=? ORDER BY t.starts_on NULLS LAST,t.id",id);return Map.of("items",rows,"total",rows.size());}
 public record Task(String name,Long assigneeId,Integer progress,LocalDate startsOn,LocalDate endsOn){}
 private void validateTask(Task t){if(t.name()==null||t.name().isBlank()||t.name().length()>200||t.progress()==null||t.progress()<0||t.progress()>100||t.startsOn()!=null&&t.endsOn()!=null&&t.endsOn().isBefore(t.startsOn()))throw bad("Task non valido");if(t.assigneeId()!=null&&db.queryForObject("SELECT count(*) FROM penny_users WHERE id=? AND enabled=true",Integer.class,t.assigneeId())==0)throw bad("Utente non disponibile");}
 @PostMapping("/api/customer-records/{id}/tasks") @Transactional public Map<String,Object> task(@PathVariable long id,@RequestBody Task t,Authentication auth){var r=owner(id,auth,true);if(!Set.of("TECHNICAL","DEVELOPMENT").contains(r.get("kind")))throw bad("I task richiedono un'attività tecnica o uno sviluppo");validateTask(t);long tid=db.queryForObject("INSERT INTO penny_record_tasks(record_id,name,assignee_id,progress,starts_on,ends_on) VALUES (?,?,?,?,?,?) RETURNING id",Long.class,id,t.name().trim(),t.assigneeId(),t.progress(),t.startsOn(),t.endsOn());audit.record(auth,"TASK_CREATED","TASK",tid,Map.of("recordId",id));return Map.of("id",tid);}
 @PutMapping("/api/customer-records/{id}/tasks/{taskId}") @Transactional public Map<String,Object> task(@PathVariable long id,@PathVariable long taskId,@RequestBody Task t,Authentication auth){owner(id,auth,true);validateTask(t);if(db.update("UPDATE penny_record_tasks SET name=?,assignee_id=?,progress=?,starts_on=?,ends_on=? WHERE id=? AND record_id=?",t.name().trim(),t.assigneeId(),t.progress(),t.startsOn(),t.endsOn(),taskId,id)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);audit.record(auth,"TASK_UPDATED","TASK",taskId,Map.of("recordId",id));return Map.of("updated",true);}
 public record Renewal(LocalDate startsOn,LocalDate expiresOn,String reason){}
 @GetMapping("/api/customer-records/{id}/renewals") public Map<String,Object> renewals(@PathVariable long id,Authentication auth){var r=owner(id,auth,false);if(!"CONTRACT".equals(r.get("kind")))throw bad("Scheda non contrattuale");var rows=db.queryForList("SELECT id,event_type AS \"eventType\",previous_start AS \"previousStart\",previous_end AS \"previousEnd\",new_start AS \"startsOn\",new_end AS \"expiresOn\",reason,actor,created_at AS \"createdAt\" FROM penny_contract_renewals WHERE record_id=? ORDER BY id DESC",id);return Map.of("items",rows,"total",rows.size());}
 @PostMapping("/api/customer-records/{id}/renewals") @Transactional public Map<String,Object> renew(@PathVariable long id,@RequestBody Renewal in,Authentication auth){var r=owner(id,auth,true);if(!"CONTRACT".equals(r.get("kind"))||in.startsOn()==null||in.expiresOn()==null||in.expiresOn().isBefore(in.startsOn())||in.reason()==null||in.reason().isBlank()||in.reason().length()>2000)throw bad("Rinnovo non valido: date e motivazione obbligatorie");var locked=db.queryForMap("SELECT starts_on,expires_on FROM penny_customer_records WHERE id=? AND deleted_at IS NULL FOR UPDATE",id);if(locked.get("expires_on")!=null&&!in.expiresOn().isAfter(LocalDate.parse(locked.get("expires_on").toString())))throw bad("Il rinnovo deve estendere la scadenza");long rid=db.queryForObject("INSERT INTO penny_contract_renewals(record_id,previous_start,previous_end,new_start,new_end,reason,actor) VALUES (?,?,?,?,?,?,?) RETURNING id",Long.class,id,locked.get("starts_on"),locked.get("expires_on"),in.startsOn(),in.expiresOn(),in.reason().trim(),auth.getName());db.update("UPDATE penny_customer_records SET starts_on=?,expires_on=?,status='ACTIVE',updated_at=now() WHERE id=?",in.startsOn(),in.expiresOn(),id);audit.record(auth,"CONTRACT_RENEWED","CUSTOMER_RECORD",id,Map.of("renewalId",rid));return Map.of("id",rid);}
 @GetMapping("/api/customer-records/{id}/interventions") public Map<String,Object> interventions(@PathVariable long id,Authentication auth){var owner=owner(id,auth,false);var rows=db.queryForList("SELECT r.id,r.name,r.reference,r.starts_on AS \"startsOn\",r.status FROM penny_record_interventions l JOIN penny_customer_records r ON r.id=l.intervention_id WHERE l.record_id=? AND r.deleted_at IS NULL AND r.customer_id=? ORDER BY r.starts_on DESC,r.id DESC",id,owner.get("customerId"));return Map.of("items",rows,"total",rows.size());}
 public record Link(Long interventionId){}
 @PostMapping("/api/customer-records/{id}/interventions") @Transactional public Map<String,Object> link(@PathVariable long id,@RequestBody Link link,Authentication auth){var r=owner(id,auth,true);if(!Set.of("TECHNICAL","DEVELOPMENT").contains(r.get("kind"))||link.interventionId()==null)throw bad("Collegamento non valido");var intervention=owner(link.interventionId(),auth,false);if(!"INTERVENTION".equals(intervention.get("kind"))||!Objects.equals(r.get("customerId"),intervention.get("customerId")))throw bad("Intervento di un altro cliente o scheda incompatibile");db.update("INSERT INTO penny_record_interventions(record_id,intervention_id) VALUES (?,?) ON CONFLICT DO NOTHING",id,link.interventionId());audit.record(auth,"INTERVENTION_LINKED","CUSTOMER_RECORD",id,Map.of("interventionId",link.interventionId()));return Map.of("linked",true);}
}
